            {text="Hold your positions!", sound="PALVP_2C1448D854E021F1138A", weight=1, durationMs=1266},
            {text="But he's dismissed!", sound="PALVP_AD2F860CAACAA9BC3E82", weight=1, durationMs=1311},
            {text="Everyone be at the ready.", sound="PALVP_8AB268CFC3A4DC4CC7E0", weight=1, durationMs=1413},
            {text="Don't leave without my command!", sound="PALVP_C36112713A9A77233378", weight=1, durationMs=1756},
