            {text="Attention! We've been detected!", sound="PALVP_835397E8EA59FF8FFA5D", weight=1, durationMs=1530},
            {text="been detected by the enemy.", sound="PALVP_C88EF0405A6EEFF05CC7", weight=1, durationMs=1762},
        },
        CONTACT_PLAYER={
            {text="Reinforcement of an eye. Now we'll show him.", sound="PALVP_4D9B1E685AD8D6E7EA33", weight=1, durationMs=2720},
            {text="Reinforcement of our life, now we show him.", sound="PALVP_139391CC86B6933D711C", weight=1, durationMs=2726},
            {text="Okay, I see we work together on this, you in?", sound="PALVP_2B927F701BE5BABD541B", weight=1, durationMs=3126},
            {text="Hey, I see, we worked together on this, you in?", sound="PALVP_B2E29E37792D13E47B3F", weight=1, durationMs=3132},
