    lines={
        AMBUSH_READY={
            {text="Squad, assume your positions!", sound="PALVP_09B4DCB61607C984AAE7", weight=1, durationMs=1905},
            {text="Scat it up in the chain. Be at the ready!", sound="PALVP_36A2F3CB6E36DB3835E7", weight=1, durationMs=2468},
        },
        BUILDING_SECURED={
            {sound="PALVP_25318FD4288707975256", weight=1, durationMs=1499},
            {text="Position captured, open.", sound="PALVP_D2716547730A61D94232", weight=1, durationMs=1516},
            {text="We've dislodes the enemy.", sound="PALVP_95AD79951242D9E1AC21", weight=1, durationMs=1691},
            {text="Base, we've dislodged the enemy.", sound="PALVP_B44825AEC1036B2D1EBD", weight=1, durationMs=1757},
            {text="The base, we've captured the target location.", sound="PALVP_64AC4B2E5E36D6F803F2", weight=1, durationMs=2520},
            {text="Base, we've captured the target location.", sound="PALVP_5B789C9DDBC78C9C4F04", weight=1, durationMs=2555},
        },
        COMBAT_END={
            {text="Keep on guard!", sound="PALVP_E48DEE5C75E01901C08A", weight=1, durationMs=788},
            {text="Stay down and wait.", sound="PALVP_F97B332936B1F3763BA1", weight=1, durationMs=912},
            {text="Sit tight where you are!", sound="PALVP_7FA886B8975F989F7039", weight=1, durationMs=1005},
            {text="Good", sound="PALVP_CAFF68C19C343FFF98E8", weight=1, durationMs=1034},
            {text="Keep your eyes peeled!", sound="PALVP_2A6181DBF0ED32F2BB6A", weight=1, durationMs=1063},
            {text="I think we got them all.", sound="PALVP_9A6B72C319BA087259EA", weight=1, durationMs=1144},
            {text="Looks all quiet to me.", sound="PALVP_BBB01C614FB3E182D957", weight=1, durationMs=1208},
            {text="That's it. Chill fellas.", sound="PALVP_B9A38EE91BD180093064", weight=1, durationMs=1498},
        },
        CONTACT_HOSTILE={
            {sound="PALVP_126E762CFB5438606823", weight=1, durationMs=1035},
            {text="And you're detected.", sound="PALVP_006BF79C3A3EFD9B9DE4", weight=1, durationMs=1049},
            {text="I see the target.", sound="PALVP_39B72CC7F6252414B4E9", weight=1, durationMs=1185},
            {text="I see the target.", sound="PALVP_FCB750F4DB0504802BF4", weight=1, durationMs=1197},
            {text="They spotted us!", sound="PALVP_4E52E7F1E1957A8BF28E", weight=1, durationMs=1612},
            {text="They spotted us!", sound="PALVP_82B49B92678D73C22488", weight=1, durationMs=1615},
            {text="in the open.", sound="PALVP_826DF2247FC4BCB57605", weight=1, durationMs=1662},
            {text="We'll have to fight out in the open.", sound="PALVP_95153780C59D496BBD9E", weight=1, durationMs=1702},
        },
        CONTACT_PLAYER={
            {text="That's it. Now we'll teach them a lesson.", sound="PALVP_7EA6862DF8AB90B45953", weight=1, durationMs=1963},
            {text="That's it. Now we'll teach them a lesson.", sound="PALVP_07D49BFFB24B1FCF93DA", weight=1, durationMs=1969},
            {text="Nice at you to come. They ain't gonna get a warm welcome now.", sound="PALVP_FD2FAD8110E94207DF46", weight=1, durationMs=2845},
            {text="Nice of you to come. They ain't gonna get a warm welcome now.", sound="PALVP_807080A203CF20C1E2FE", weight=1, durationMs=2880},
            {text="Thanks for coming to our help. Let's show them who's boss.", sound="PALVP_0A9951B1BC151A5A2B91", weight=1, durationMs=2892},
            {text="Thanks for coming to our help. Let's show them who's boss.", sound="PALVP_7D59FD79833D8D73528D", weight=1, durationMs=2892},
        },
        LOST_TARGET={
            {text="I lost him. Wait, let me use this.", sound="PALVP_A678991A0F701D25CC1D", weight=1, durationMs=2383},
        },
        MOVE_OUT={
            {text="Spread! Move out!", sound="PALVP_B4E4E19D5A029D181FC9", weight=1, durationMs=1336},
            {text="I wonder who did I need to? We're moving out.", sound="PALVP_DCB7B08106702642BCE2", weight=1, durationMs=3180},
        },
        ORDER_ACK={
            {text="We're on it!", sound="PALVP_56E66729BB9977D95D73", weight=1, durationMs=1252},
        },
        RAID_START={
            {text="Squad, follow me!", sound="PALVP_8D7B7CEF28AC6CC0DA56", weight=1, durationMs=1214},
            {text="Attack on my signal!", sound="PALVP_953AEE3B0126D3AB259F", weight=1, durationMs=1244},
            {text="Get him!", sound="PALVP_B41F754423C1E20E1CEC", weight=1, durationMs=1307},
            {text="Don't attack without my command!", sound="PALVP_1CA30DF95EDA9EBBAB77", weight=1, durationMs=1736},
            {text="I'm done, fire it!", sound="PALVP_3A8969D47AB230683F33", weight=1, durationMs=1853},
            {text="Shoot only on my command!", sound="PALVP_4BF89D4BB6015FE98688", weight=1, durationMs=2062},
            {text="The enemy never slips, get ready!", sound="PALVP_2FE2E50781DDE58494B0", weight=1, durationMs=2152},
            {text="Because I'm responding. Something about to happen to them.", sound="PALVP_4DF26A76485D620946DD", weight=1, durationMs=3166},
        },
        SPREAD_OUT={
            {text="Everyone spread out!", sound="PALVP_7CD0D56BE022E6598890", weight=1, durationMs=1093},
        },
        TIRED={
            {text="Boy, am I tired of these trips?", sound="PALVP_C36DADB36773C6B7B7A3", weight=1, durationMs=1916},
        },
        WARNING_LOWER_WEAPON={
            {text="Put that piece away.", sound="PALVP_D883FD2C188376B44C12", weight=1, durationMs=1554},
            {text="Put that gun away then we'll talk.", sound="PALVP_EF84A66269048E6DA918", weight=1, durationMs=1860},
            {text="First, you put that gun away.", sound="PALVP_DCF191B0CC11572A5A94", weight=1, durationMs=2021},
            {text="holster that weapon if you want to talk", sound="PALVP_13E6FD364B75D7A3136D", weight=1, durationMs=2096},
            {text="I said put that shooter behind your back.", sound="PALVP_71069EE7711961FC701D", weight=1, durationMs=2491},
        },
    },
})

