    lines={
        AMBUSH_READY={
            {text="Fighters are in position. Just signal when.", sound="PALVP_BA42D23FB28157A9EF3D", weight=1, durationMs=3024},
            {text="Fighters are in position. Just signal when.", sound="PALVP_8A2E0C31E6929129BB66", weight=1, durationMs=3054},
            {text="Attention! Everyone take your positions!", sound="PALVP_02BA224E480F1882267F", weight=1, durationMs=3006},
        },
        BUILDING_SECURED={
            {text="reporting enemy driven off", sound="PALVP_A573A85E8B41AE0A0EF5", weight=1, durationMs=2188},
            {text="reporting enemy driven off", sound="PALVP_42DAA92C77EC2B9FA391", weight=1, durationMs=2207},
            {text="Roger, the position is under our control.", sound="PALVP_7A307A61E8EF9CC9DE3F", weight=1, durationMs=3084},
            {text="Roger, the position is under our control.", sound="PALVP_1F4282A008E3276415F0", weight=1, durationMs=3098},
            {text="Location capture, awaiting further instructions.", sound="PALVP_07AE4460E095DA5DCB79", weight=1, durationMs=3488},
            {text="Location capture, awaiting further instructions.", sound="PALVP_1F56EE48B4E8BE2C68DC", weight=1, durationMs=3495},
        },
        COMBAT_END={
            {text="Look around!", sound="PALVP_643F59278C6A34EB9086", weight=1, durationMs=1037},
            {sound="PALVP_C33AA476ED79B6C204DB", weight=1, durationMs=1100},
            {text="At ease, dismissed.", sound="PALVP_129E68CABF021BEAD25E", weight=1, durationMs=1604},
            {sound="PALVP_4C9C09D9B3AED34F0C65", weight=1, durationMs=1634},
            {text="Everyone, be at the ready!", sound="PALVP_9948D515FF32DA0837E6", weight=1, durationMs=1798},
            {text="We knocked the bastards out!", sound="PALVP_B3ECE0878A8AB5FF2D98", weight=1, durationMs=1832},
            {text="The territory is ours.", sound="PALVP_F9243952B254471B8F61", weight=1, durationMs=1849},
            {text="Don't leave without my command!", sound="PALVP_77497AC36CE2D54715F8", weight=1, durationMs=1911},
        },
        CONTACT_HOSTILE={
            {text="I see the enemy.", sound="PALVP_2A8DDDA65EF29EAEF76F", weight=1, durationMs=1074},
            {text="I see the enemy!", sound="PALVP_F381D08851B34C4F7A8C", weight=1, durationMs=1081},
            {text="The enemy spotted.", sound="PALVP_5CD50282329D8447B5A3", weight=1, durationMs=1202},
            {sound="PALVP_E04B05DBC4B70D6352C2", weight=1, durationMs=1202},
            {text="We've given ourselves away!", sound="PALVP_6D7D9A71F5D6C4773C41", weight=1, durationMs=1628},
            {text="We've given ourselves away.", sound="PALVP_FC733308941652D0FAB4", weight=1, durationMs=1651},
            {text="We've been detected by the enemy.", sound="PALVP_5DF5C838898B0D598207", weight=1, durationMs=1996},
            {text="We've been detected by the enemy.", sound="PALVP_09E1C5EC5469BDCF1FAF", weight=1, durationMs=2004},
        },
        CONTACT_PLAYER={
            {text="Reinforcements have arrived. Now we'll show them.", sound="PALVP_66D4A6C92E3944C8B026", weight=1, durationMs=3009},
            {text="Reinforcement how arrived. Now we'll show them.", sound="PALVP_8389C8E76710FF2964ED", weight=1, durationMs=3022},
            {text="Hey, I see we work together on this, you in?", sound="PALVP_60F9D5B6E21649906B9D", weight=1, durationMs=3047},
            {text="Hey, I see we work together on this. You in?", sound="PALVP_59C642A305E81B5A76A3", weight=1, durationMs=3066},
            {text="Finally, what the world means is more good guys like you.", sound="PALVP_F0B902C6C740349D1B5A", weight=1, durationMs=3802},
            {text="Finally, what the world needs is more good guys like you!", sound="PALVP_1C98609432E69A980E19", weight=1, durationMs=3803},
        },
        MOVE_OUT={
            {text="Yeah, anything could happen. Moving out.", sound="PALVP_71D0E5A8FDA3BD0E408D", weight=1, durationMs=3777},
        },
        RAID_START={
            {text="Open fire!", sound="PALVP_653586587BD9CEDF9686", weight=1, durationMs=998},
            {sound="PALVP_483BA93B11283DDE7FAE", weight=1, durationMs=1339},
            {text="Check your weapons and follow the leader!", sound="PALVP_1FEA5F1EFF4EF33E421B", weight=1, durationMs=2283},
            {text="Attention! Get ready for action!", sound="PALVP_7962BF7C1785304BCA26", weight=1, durationMs=2522},
            {text="Wait, don't open fire till I say so.", sound="PALVP_4A6D4118283EEF79710A", weight=1, durationMs=2892},
            {text="Keep your eyes peeled, at back on my command.", sound="PALVP_CDF792973B717F207074", weight=1, durationMs=2958},
            {text="Should be before I give the command and you'll be sitting on a bag.", sound="PALVP_D79DC2AF9E52B2090FC6", weight=1, durationMs=3528},
            {text="Alright, did the squad play the end of the world? Or would it be responding?", sound="PALVP_1FBD97088573D3372110", weight=1, durationMs=5098},
        },
        SPREAD_OUT={
            {text="Spread out!", sound="PALVP_3221B70844A435586D1B", weight=1, durationMs=960},
            {text="Spread out and get ready for action!", sound="PALVP_2F14149EE16D313F186E", weight=1, durationMs=2334},
        },
        TIRED={
            {text="I'm getting tired of waiting!", sound="PALVP_B4419355DF77F15F060B", weight=1, durationMs=2086},
        },
        WARNING_LOWER_WEAPON={
            {text="Put that weapon away, Chief.", sound="PALVP_0396C00002ECC82B1B38", weight=1, durationMs=1467},
            {text="Put that weapon away man!", sound="PALVP_CC3B6437235E448CFAC0", weight=1, durationMs=1719},
            {text="Put that gun away now!", sound="PALVP_CEC6C5A6BB018BF2F096", weight=1, durationMs=1978},
            {text="We'll talk when you holster your weapon.", sound="PALVP_C2868D8C4EB503E558BD", weight=1, durationMs=2093},
            {text="Did you forget how to holster weapon?", sound="PALVP_23A899AC19B9A4B17E6F", weight=1, durationMs=2408},
            {text="either put the shooter away or just go away.", sound="PALVP_02C541ACB2114BAC16D9", weight=1, durationMs=3148},
        },
    },
})

