    lines={
        ASK_MEDICAL={
            {text="Got it!", sound="PALVP_08D8DC3B57948C164212", weight=1, durationMs=588},
            {text="Take it down!", sound="PALVP_977BFEA4788FE3632A06", weight=1, durationMs=912},
            {text="Tangle down!", sound="PALVP_3F1C62E015B050D2CAFF", weight=1, durationMs=1030},
            {sound="PALVP_A01C70F4CEBB5CF7D047", weight=1, durationMs=1268},
            {text="You'll be okay, pal. You'll be okay.", sound="PALVP_A4F403D1870839D1513F", weight=1, durationMs=2116},
            {text="Here's the med kit buddy. I hope it will be useful.", sound="PALVP_B0903EC142749C727BC4", weight=1, durationMs=4598},
            {text="Outside, we're status green over here. Retangled down. Has the grease over.", sound="PALVP_5A2D5AC2109F33E5C529", weight=1, durationMs=4883},
            {text="Hold on, I'm batching you up. Get on your feet, soldier. The fight's done over yet.", sound="PALVP_B8D299243DC7C0A7E5C3", weight=1, durationMs=4989},
        },
        BREACH={
            {text="Security breach! I need backup!", sound="PALVP_67A0B58E06B10EE0ACE9", weight=1, durationMs=2501},
        },
        COMBAT_END={
            {text="We've got a moment to relax.", sound="PALVP_F68AC8523340E030E37E", weight=1, durationMs=1802},
            {text="Take it easy for a minute.", sound="PALVP_469F450698644DEB8D54", weight=1, durationMs=1881},
            {text="Oh, steady.", sound="PALVP_87356F616A8FD63EF2C9", weight=1, durationMs=1881},
            {text="Enjoy the quiet while at last.", sound="PALVP_9D6DEE0B9D59E275027D", weight=1, durationMs=2038},
            {text="Standing by for further orders.", sound="PALVP_CF28EB9067C72D54365D", weight=1, durationMs=2116},
            {text="Nothing happening for now.", sound="PALVP_DD6BF1ABDB1357C6AD72", weight=1, durationMs=2194},
            {text="Keep your eyes open. We wait.", sound="PALVP_DA6EE1BB0E314B3B3A0F", weight=1, durationMs=2351},
        },
        CONTACT_HOSTILE={
            {text="May take a classic posture, stand visual contact with the target.", sound="PALVP_32160E9F37C79A065C39", weight=1, durationMs=3486},
            {text="May take a classic posture, stand visual contact with the target.", sound="PALVP_4B018F75B506F0667F12", weight=1, durationMs=3486},
            {text="Stand frosting, keep it professional. Headshots, holy.", sound="PALVP_9428051B94395012C3E2", weight=1, durationMs=3151},
        },
        COVER_ME={
            {sound="PALVP_DABFB38C0D5957EA0F7B", weight=1, durationMs=2194},
            {sound="PALVP_55B83608B61821DE447D", weight=1, durationMs=1228},
            {sound="PALVP_8AE081A33AD724C2195D", weight=1, durationMs=1228},
            {sound="PALVP_779E0B0DE6A0ADD5B324", weight=1, durationMs=1411},
            {sound="PALVP_6DD78ABD863545C4F8E9", weight=1, durationMs=1646},
        },
        FLANK_START={
            {text="We'll sit there, flake!", sound="PALVP_432C7070862381B2E358", weight=1, durationMs=1149},
            {text="Taking the warm one!", sound="PALVP_7B33A30ADB2DE04740F3", weight=1, durationMs=1411},
            {sound="PALVP_3E69C985F507FD54B9D0", weight=1, durationMs=1489},
            {sound="PALVP_B0CBE539064C137AE6D0", weight=1, durationMs=1646},
            {text="We'll strike from a flank!", sound="PALVP_1798C15C567CAB69AE38", weight=1, durationMs=1802},
            {sound="PALVP_9EFC21E227F542FF5972", weight=1, durationMs=1802},
            {text="Head to from another side.", sound="PALVP_C5B7230801AD433905D4", weight=1, durationMs=1802},
            {sound="PALVP_A9C601AE2D2429E3CE8D", weight=1, durationMs=2116},
        },
        FRIENDLY_FIRE={
            {sound="PALVP_7579FCDFD489FE6ACFDB", weight=1, durationMs=1116},
            {text="Check your bar!", sound="PALVP_F589DEFA23CDAF4CF709", weight=1, durationMs=1138},
            {text="Find the choir! Find the choir!", sound="PALVP_EB5061AE11D153FEBEB9", weight=1, durationMs=1690},
            {text="Check your fire!", sound="PALVP_62AB5E765523F1D13C8E", weight=1, durationMs=1959},
            {sound="PALVP_DCD34A6A543D41B34534", weight=1, durationMs=1363},
            {sound="PALVP_B9482CB0D4B8F2744E28", weight=1, durationMs=1411},
        },
        HURT={
            {text="Oh!", sound="PALVP_C7D9C88E09AD0F2672A0", weight=1, durationMs=312},
            {sound="PALVP_9717C86B04F687115E1B", weight=1, durationMs=313},
            {text="I...", sound="PALVP_560046535B8F4CC127C4", weight=1, durationMs=345},
            {text="Oh!", sound="PALVP_02CA7FDFB7345DA273DB", weight=1, durationMs=397},
            {text="No!", sound="PALVP_1B7937A5647F1C68659D", weight=1, durationMs=492},
            {sound="PALVP_70EC3F5837B2F64F5DA0", weight=1, durationMs=210},
            {sound="PALVP_C8C21F40D479D41CBCDD", weight=1, durationMs=211},
            {sound="PALVP_55FCD821AE2C38864152", weight=1, durationMs=300},
            {sound="PALVP_004D0392E6FA2E4A8246", weight=1, durationMs=370},
            {sound="PALVP_D809318B7FF3A935CF02", weight=1, durationMs=3082},
            {sound="PALVP_7C0B8B0F5BD17912C50B", weight=1, durationMs=3971},
            {sound="PALVP_282B78B9E4ECF114C6A8", weight=1, durationMs=4833},
        },
        JOKE={
            {text="I'll give you that", sound="PALVP_F814C660B12E78C4C4F9", weight=1, durationMs=1802},
            {text="I didn't expect that one.", sound="PALVP_07D6870F3E50CB496053", weight=1, durationMs=2116},
            {text="It's a mutant, sir, that joke, they'd run away.", sound="PALVP_FD4071D9925727A4B721", weight=1, durationMs=2769},
            {text="you might survive as a comedian.", sound="PALVP_09DD8323BCFC1675BABD", weight=1, durationMs=2847},
            {text="Maybe spill my drink!", sound="PALVP_E12EC4336FFE5BAD6088", weight=1, durationMs=2926},
            {text="Good campfire story.", sound="PALVP_0EF2A7F856452D33BD89", weight=1, durationMs=3004},
            {text="Careful, keep telling jokes like that, we might forget where we are.", sound="PALVP_6E330F644D144C303738", weight=1, durationMs=3788},
            {sound="PALVP_CEBFF1CD6C3503A0F967", weight=1, durationMs=2351},
        },
        KILL_CONFIRMED={
            {text="Got it!", sound="PALVP_0F6E154914A97F0F2EBB", weight=1, durationMs=588},
            {text="Take it down!", sound="PALVP_F8BE959609B2FC7146D1", weight=1, durationMs=912},
            {text="Tangle down!", sound="PALVP_34C04B8BE44E91898E0D", weight=1, durationMs=1030},
            {sound="PALVP_28FBF1FBF37BE82C853F", weight=1, durationMs=1249},
            {sound="PALVP_005FA39F04CA79F25E54", weight=1, durationMs=1268},
            {sound="PALVP_2637228BCED91DB32C2E", weight=1, durationMs=1411},
            {sound="PALVP_75CEE3F1E3E57978A994", weight=1, durationMs=1802},
        },
        MOVE_OUT={
            {text="Let's go, let's go, let's go, let's build the offensive!", sound="PALVP_4C9C363EFA41F8015F7B", weight=1, durationMs=2179},
        },
        MULTIPLE_CONTACTS={
            {sound="PALVP_8EC6BB5FE29EF841B656", weight=1, durationMs=1572},
        },
        RETREAT={
            {text="Alpatine, fall back to Rally Point Chester.", sound="PALVP_7499E82345FC536C495B", weight=1, durationMs=2363},
        },
        SEARCH_START={
            {text="Who was that?", sound="PALVP_F1FC32A89E1478384470", weight=1, durationMs=441},
            {text="Someone there?", sound="PALVP_F07A895EB54D5CAF97EC", weight=1, durationMs=682},
            {text="Okay, someone there.", sound="PALVP_5F6CC057626D0DAAAF36", weight=1, durationMs=772},
            {text="How was that noise?", sound="PALVP_8DF2C4FE077EB71FE3D9", weight=1, durationMs=890},
            {text="I'm still there.", sound="PALVP_7E3F5AAFED1D557A525C", weight=1, durationMs=1018},
            {text="Put the hell with that!", sound="PALVP_ADFF4BD581FC73FFDEF2", weight=1, durationMs=1153},
            {text="I think I see something.", sound="PALVP_017D55FD2A4A06456DB9", weight=1, durationMs=1347},
            {text="There's something step by.", sound="PALVP_B753849C11B88B081354", weight=1, durationMs=1351},
            {text="We have a situation here.", sound="PALVP_D0B08E5A4539E6583802", weight=1, durationMs=1433},
            {text="I didn't find anything but Stailer.", sound="PALVP_BFE5DE9D1F124808FEE5", weight=1, durationMs=1799},
        },
        STATUS_OK={
            {text="There you some beers! Much appreciated!", sound="PALVP_9D6578466BF040C3779A", weight=1, durationMs=2847},
            {text="Yet!", sound="PALVP_D236B011DE3E0F844886", weight=1, durationMs=2847},
            {text="Thank you.", sound="PALVP_BA47F5EB5478C8D0949A", weight=1, durationMs=3239},
            {text="Ah, thanks.", sound="PALVP_0EA3C0EE1E049F220FB5", weight=1, durationMs=3318},
            {sound="PALVP_C425CE3C34631DEA5F63", weight=1, durationMs=3971},
            {text="Hi, I just owe you one.", sound="PALVP_A6D40014BF9DF593B58F", weight=1, durationMs=4989},
        },
        WARNING_LOWER_WEAPON={
            {text="Drop your weapon, drop it now!", sound="PALVP_844BE6AD95B3EA4D68DD", weight=1, durationMs=1529},
            {text="Come on man, stay your rookie and put that gun away!", sound="PALVP_EF4F80F3196962646DBC", weight=1, durationMs=3971},
            {text="Let's not do anything stupid. Lower the gun.", sound="PALVP_67C42EDF4C780B9CED53", weight=1, durationMs=4754},
        },
