    lines={
        ASK_MEDICAL={
            {text="He's out.", sound="PALVP_1002FA26281EAB32B048", weight=1, durationMs=1149},
            {text="He's done.", sound="PALVP_D28E9DF6A45DEE53D537", weight=1, durationMs=1306},
            {text="That's one less problem.", sound="PALVP_23CDB2A5C8169022A1E3", weight=1, durationMs=1802},
            {text="He won't be getting back up.", sound="PALVP_8F4633BB7340F5E7F5B6", weight=1, durationMs=1802},
            {text="I got you buddy, I got you.", sound="PALVP_8AD0CE02F3815A56F0C7", weight=1, durationMs=1959},
            {text="die on me.", sound="PALVP_4F0BAA6668122F990B79", weight=1, durationMs=2273},
            {text="Take this, it'll patch you up.", sound="PALVP_EF83D2DC259A8751279E", weight=1, durationMs=2273},
            {sound="PALVP_7EEA95CFB607E9131883", weight=1, durationMs=2586},
        },
        COMBAT_END={
            {text="God it's over.", sound="PALVP_6956F80B875002157C96", weight=1, durationMs=1802},
            {text="I'm standing by for further instructions.", sound="PALVP_32F884C7234E7F3A2E74", weight=1, durationMs=2194},
            {text="I should eat a snack while I can.", sound="PALVP_77AA1016938F05F84441", weight=1, durationMs=2194},
            {text="I'm going to refill my mags now.", sound="PALVP_792F3B3A176BD0F1EED0", weight=1, durationMs=2351},
            {text="I must be ready for any possible threats in the area.", sound="PALVP_FDA779853325D904F128", weight=1, durationMs=2926},
            {text="HQ is sending me new instructions. I should check what this is about.", sound="PALVP_95F90D821718E08916D1", weight=1, durationMs=3788},
            {text="Well, standing here in the middle of nowhere in Ukraine, I guess it's paradise. Kind of.", sound="PALVP_D9414C2DB67EB123E1DA", weight=1, durationMs=8986},
        },
        CONTACT_HOSTILE={
            {text="Hostile spotted in the vicinity.", sound="PALVP_A2F238DD9A29E6E27C99", weight=1, durationMs=2586},
            {text="over here.", sound="PALVP_CCF6BEB526F89356127C", weight=1, durationMs=1959},
            {text="Intruder over there", sound="PALVP_5A0227D6C2D2762E8BC1", weight=1, durationMs=2194},
        },
        COVER_ME={
            {text="They're so fire!", sound="PALVP_9E2658EFFDC796F3C113", weight=1, durationMs=1489},
            {text="Suppressive fire!", sound="PALVP_2550E28DE30E522CF0A4", weight=1, durationMs=1724},
            {text="Cover fire!", sound="PALVP_43E2A04DB5C8545E93A3", weight=1, durationMs=1724},
            {text="Covering fire!", sound="PALVP_61CD2681F6146064FEB6", weight=1, durationMs=1724},
            {text="laying down suppressive fire.", sound="PALVP_28B6C1B635C78AFE3FD1", weight=1, durationMs=1959},
            {text="Playing down some covering fire.", sound="PALVP_B6C455DC2092C9545151", weight=1, durationMs=2194},
        },
        FLANK_START={
            {text="Go wide!", sound="PALVP_44CDD07E2CE7B467FD9B", weight=1, durationMs=1489},
            {text="Straight their flank!", sound="PALVP_5B0DBA0F06485BD056B5", weight=1, durationMs=1489},
            {text="Attack left flank!", sound="PALVP_3FE31D33070C05689F16", weight=1, durationMs=1802},
            {text="Great contact, reposition.", sound="PALVP_6FA7E17886C8F7BE1A60", weight=1, durationMs=1881},
            {text="Swissing Approach Vector!", sound="PALVP_7799EBC1FC38A7AA887C", weight=1, durationMs=1881},
            {text="Shift axis of advance.", sound="PALVP_10F740A27DF15FC6E470", weight=1, durationMs=2038},
            {text="Attack right flank!", sound="PALVP_D8297A2EFE7F0680CA5D", weight=1, durationMs=2038},
            {text="Offset approach, keep low.", sound="PALVP_C6A9C44537803EB32A7A", weight=1, durationMs=2194},
        },
        FRIENDLY_FIRE={
            {text="Watch your fire!", sound="PALVP_0738C185D50DE7A6FC10", weight=1, durationMs=1724},
            {text="Check your fire soldier!", sound="PALVP_482D20E7D5FEC301C7A7", weight=1, durationMs=2038},
            {text="Friendly fire, friendly fire!", sound="PALVP_8E2DD4676A41E14ECCBC", weight=1, durationMs=2038},
            {text="Watch your goddamn sectors!", sound="PALVP_757CFC59B29A03277401", weight=1, durationMs=2926},
            {text="Hey watch it asshole!", sound="PALVP_D4DED566FF4E939EB748", weight=1, durationMs=3239},
        },
        HUNGRY={
            {text="Time to top off food supplies. I need food, water and meds before moving. And I better check ammo count. Can't risk going dry.", sound="PALVP_AA17561D307D8ED06192", weight=1, durationMs=8359},
        },
        HURT={
            {text="Oh!", sound="PALVP_C7D9C88E09AD0F2672A0", weight=1, durationMs=312},
            {sound="PALVP_9717C86B04F687115E1B", weight=1, durationMs=313},
            {text="I...", sound="PALVP_560046535B8F4CC127C4", weight=1, durationMs=345},
            {text="Oh!", sound="PALVP_02CA7FDFB7345DA273DB", weight=1, durationMs=397},
            {text="No!", sound="PALVP_1B7937A5647F1C68659D", weight=1, durationMs=492},
            {text="I'm fucking hit! I'm hit!", sound="PALVP_399DFB8EF7B8CA43C55D", weight=1, durationMs=2429},
            {text="I'm down. I need a med kid.", sound="PALVP_46143C13A162F9ECE180", weight=1, durationMs=3161},
            {text="Ugh, they got me! I'm down!", sound="PALVP_F5A6D3B882652C0A4756", weight=1, durationMs=3318},
            {sound="PALVP_392D5242D04205F1E86A", weight=1, durationMs=4049},
            {sound="PALVP_70EC3F5837B2F64F5DA0", weight=1, durationMs=210},
            {sound="PALVP_C8C21F40D479D41CBCDD", weight=1, durationMs=211},
            {sound="PALVP_55FCD821AE2C38864152", weight=1, durationMs=300},
            {sound="PALVP_004D0392E6FA2E4A8246", weight=1, durationMs=370},
        },
        JOKE={
            {sound="PALVP_283CA25D0A697462C8FC", weight=1, durationMs=993},
            {text="All right.", sound="PALVP_2F69480AA2DDEDE5671A", weight=1, durationMs=1881},
            {text="I understand.", sound="PALVP_5FAECE3E1119E4DE0014", weight=1, durationMs=1959},
            {text="Well, I guess that works.", sound="PALVP_09D6AE39680C76C4FA25", weight=1, durationMs=2769},
            {sound="PALVP_76007869F25306E72EC8", weight=1, durationMs=2769},
            {text="Found a glowing artifact, thought it was rare. Rookie grabs it, says, careful. I put it in my pack. Turns out it was a radioactive coffee mug. At least I'm awake for the next 48 hours.", sound="PALVP_8E42F8CD71CD2B832532", weight=1, durationMs=10684},
            {sound="PALVP_ED9044F70A2DB8EABD2B", weight=1, durationMs=601},
            {sound="PALVP_EA592924078735AEDA00", weight=1, durationMs=914},
            {sound="PALVP_25533629DFF2A93D1B60", weight=1, durationMs=2273},
        },
        KILL_CONFIRMED={
            {text="He's down!", sound="PALVP_3283E76DC6288D63114D", weight=1, durationMs=1228},
            {text="Target down!", sound="PALVP_BA33784B34016EC8A6A9", weight=1, durationMs=1646},
            {text="enemy down", sound="PALVP_9301B2E6C230B4AC38E5", weight=1, durationMs=1724},
            {text="Contact eliminated.", sound="PALVP_73F1625516408F017E22", weight=1, durationMs=1802},
            {text="Contact neutralized.", sound="PALVP_B56FBBA55119ED336135", weight=1, durationMs=1881},
            {text="Hostile neutralized!", sound="PALVP_BD3434F26638BC850FA0", weight=1, durationMs=1881},
            {text="Tango down!", sound="PALVP_D22E53C29C2FE450A5B9", weight=1, durationMs=2194},
            {text="Threat neutralized.", sound="PALVP_371534504BC1983DA617", weight=1, durationMs=2351},
        },
        MULTIPLE_CONTACTS={
            {text="Multiple targets in my sights.", sound="PALVP_4A1F1D8EE7D9D8BE5A34", weight=1, durationMs=2038},
        },
        REGROUP={
            {text="I need some backup ASAP over.", sound="PALVP_5F4D177940E521AAEDBA", weight=1, durationMs=3161},
            {text="All available operators, I need backup on my location.", sound="PALVP_9EFECC3DCC8E772E847C", weight=1, durationMs=3866},
            {text="Requesting ground support on my position. I'm sending the coordinates.", sound="PALVP_137F954491A6046EAA47", weight=1, durationMs=4127},
            {text="I'm pinned down requesting immediate assistance on my position.", sound="PALVP_9CC3DBC94E6698761FBA", weight=1, durationMs=5068},
        },
        SEARCH_START={
            {text="I lost visual.", sound="PALVP_18EC551EC5819B4D5969", weight=1, durationMs=1306},
            {text="Enemy lost.", sound="PALVP_CA954A91A30391F61702", weight=1, durationMs=1306},
            {text="Is someone there?", sound="PALVP_22AFEC18284772BE56F1", weight=1, durationMs=1489},
            {sound="PALVP_38D2F86F256EB6C4CEA9", weight=1, durationMs=1567},
            {text="I lost visual contact with the target.", sound="PALVP_1FD8B270DC69BC4096B3", weight=1, durationMs=2038},
            {text="Come on, I know you're there.", sound="PALVP_673233C8CCF521E42B1B", weight=1, durationMs=2273},
            {text="The target just vanished.", sound="PALVP_DA52B073D181806E249E", weight=1, durationMs=2273},
            {text="Target is no longer in my line of sight.", sound="PALVP_E9FD7600719A5DA11BCA", weight=1, durationMs=2273},
            {text="Last warning!", sound="PALVP_F3CF66C2BF59557E55EF", weight=1, durationMs=2508},
            {text="Establish perimeter and sweep inward over.", sound="PALVP_5133386D0E25E6A3C958", weight=1, durationMs=2586},
        },
        STATUS_OK={
            {text="Back in the fight, thanks to you.", sound="PALVP_975035ED9A1AC88695A8", weight=1, durationMs=2586},
            {text="Thanks. Don't expect me to hug you.", sound="PALVP_D7387D792D91828FBC65", weight=1, durationMs=2769},
            {text="Thanks. I've got work to do.", sound="PALVP_CCF75708254CCFFFB0EB", weight=1, durationMs=2926},
            {text="Appreciated. Don't let it go to your head.", sound="PALVP_49AC01C89BE3912EC7B8", weight=1, durationMs=3082},
            {text="Thanks. Didn't think I'd see this far.", sound="PALVP_3379481EE61BB7957D28", weight=1, durationMs=3318},
            {text="Save me again", sound="PALVP_4FE49BD52D0CD9F47BBF", weight=1, durationMs=4049},
            {text="Took your sweet time, huh? Just kidding. Thanks", sound="PALVP_192F22EF523EDCEC38D2", weight=1, durationMs=4284},
        },
        TAKING_COVER={
            {text="Hands in the air, get down.", sound="PALVP_3ED83076A9452FF50C9D", weight=1, durationMs=1959},
        },
        UNDER_FIRE={
            {text="Damn. Extraction under fire. I remember every second.", sound="PALVP_33A1B61571AECE2EBA11", weight=1, durationMs=4989},
        },
        WARNING_LOWER_WEAPON={
            {text="Drop your weapon and step out.", sound="PALVP_5FCA8B3EBAFDD6D7370A", weight=1, durationMs=1881},
            {text="Drop your weapon, drop it now!", sound="PALVP_74FAB804F520C0B07E0A", weight=1, durationMs=2429},
        },
    },
})

