            {sound="PALVP_18ADEF4CE544CD77190C", weight=1, durationMs=1540},
            {text="I did my rascal, my horn!", sound="PALVP_453862D27C60DFA331BB", weight=1, durationMs=1837},
            {sound="PALVP_4D6E34138912536C6B8D", weight=1, durationMs=1304},
        },
        RAID_START={
