            {text="I'm going to Paris, and yeah.", sound="PALVP_EAD225426FA6537356BC", weight=1, durationMs=1310},
            {sound="PALVP_2B7C08D491F2CDE26752", weight=1, durationMs=1472},
            {text="Right here, it's very good. We're holding them.", sound="PALVP_91E0BD9BB085BC412EA0", weight=1, durationMs=1667},
            {sound="PALVP_856C0A22D6F07B643C14", weight=1, durationMs=1820},
        },
        REGROUP={
            {text="Not to be.", sound="PALVP_E4C9214EDF9E7E6950A3", weight=1, durationMs=1002},
            {text="Oh, it's my ass.", sound="PALVP_F45A62F9B13093012DC8", weight=1, durationMs=1097},
            {sound="PALVP_BEE79863AC64588766F3", weight=1, durationMs=1115},
            {sound="PALVP_1A7CC133A280B50793C4", weight=1, durationMs=1253},
        },
        SEARCH_START={
            {sound="PALVP_BC58AD427BB4FAE21313", weight=1, durationMs=2756},
            {sound="PALVP_2DE2D830D2F21FB93173", weight=1, durationMs=3718},
            {text="Oh, oh, there! We quite saw my thumbs up just in the roast, but I'm off.", sound="PALVP_739D14A3A6903B2FF055", weight=1, durationMs=3852},
            {sound="PALVP_0D906D347BF41BF9B3EF", weight=1, durationMs=5502},
