        },
        WARNING_STOP={
            {sound="PALVP_E0CA15F40824557DBAC3", weight=1, durationMs=1717},
            {text="So anyway, I had two of the look. It's yes, sir.", sound="PALVP_335CBC48FD818672F027", weight=1, durationMs=1833},
