            {sound="PALVP_3F547B97BBF733978EDB", weight=1, durationMs=2507},
            {sound="PALVP_C6FB4CFFA01AE612ED1E", weight=1, durationMs=3637},
            {sound="PALVP_39E356FAF66A3C6A43E0", weight=1, durationMs=4785},
        },
        JOKE={
            {text="You sure?", sound="PALVP_3D86201E5E9FD2F9307C", weight=1, durationMs=544},
            {sound="PALVP_69FE78C5F6FAAE752B6D", weight=1, durationMs=3068},
        },
        KILL_CONFIRMED={
            {sound="PALVP_A13E27BA76F4F9FD4081", weight=1, durationMs=1142},
            {text="Yeah, I hope you're so cute.", sound="PALVP_2C5D0DB414AAB0E8DE79", weight=1, durationMs=1366},
            {sound="PALVP_B67DFD4A0278BD049E40", weight=1, durationMs=2083},
            {sound="PALVP_EFB9808E6DB8913355C0", weight=1, durationMs=2535},
            {sound="PALVP_81A3B2F9A34BDC783485", weight=1, durationMs=3079},
