            {sound="PALVP_1A380536C68898931946", weight=1, durationMs=1550},
            {text="Let's get out.", sound="PALVP_840AA8093B048AFA4D13", weight=1, durationMs=1801},
            {text="I need more rust gacks, my horn!", sound="PALVP_F0A8F7C5AE6332B7A0E7", weight=1, durationMs=1847},
