            {sound="PALVP_D9324CEA50FA2B284176", weight=1, durationMs=8892},
        },
        RAID_START={
            {sound="PALVP_A2C8F2D53C92E3516669", weight=1, durationMs=827},
            {text="video", sound="PALVP_F1142D59951D2222677B", weight=1, durationMs=867},
            {text="I'm going to Paris any air.", sound="PALVP_CA2237C924FC43FBD3B9", weight=1, durationMs=1320},
            {sound="PALVP_0C4C7A42E04BA117245D", weight=1, durationMs=1482},
            {sound="PALVP_03C3B6D419E95C89D428", weight=1, durationMs=1677},
            {text="But you have a question, would you gain there?", sound="PALVP_8896CE164B91A8A08E00", weight=1, durationMs=1830},
            {sound="PALVP_1EF57A5C8D58CCD85F02", weight=1, durationMs=2989},
        },
        REGROUP={
