            {sound="PALVP_08F6CE296E221531D4F3", weight=1, durationMs=2576},
        },
        ASK_MEDICAL={
            {text="Sure, it's three bucks for you.", sound="PALVP_7AAFACB6677892B87024", weight=1, durationMs=1355},
            {sound="PALVP_52BCC2B4E78FEA019B23", weight=1, durationMs=2979},
            {sound="PALVP_CFF21CDB6BAC129132D6", weight=1, durationMs=3939},
            {sound="PALVP_41034A0A10FF941FB59F", weight=1, durationMs=4769},
        },
        COMBAT_END={
            {sound="PALVP_1BA1F277774C4C1F4DE9", weight=1, durationMs=946},
            {sound="PALVP_B472F87D9CAB948BC83C", weight=1, durationMs=1158},
            {sound="PALVP_80ECB164791F97CB88FD", weight=1, durationMs=1509},
            {text="I'm so glad that it's put you up here!", sound="PALVP_6E6C038D65746CD9A5B9", weight=1, durationMs=2215},
            {text="Let's pop here. Let's do it this year.", sound="PALVP_8603F4442487240F94CC", weight=1, durationMs=2415},
        },
        CONTACT_HOSTILE={
            {text="Did you ask that again?", sound="PALVP_C007D874258D954157E9", weight=1, durationMs=1137},
            {sound="PALVP_9F067A1C827BAAA94B7C", weight=1, durationMs=1217},
            {sound="PALVP_0701CDBD648DC69B91E7", weight=1, durationMs=1248},
            {text="Moozek! Moozek!", sound="PALVP_586A2C8CD96BF3044940", weight=1, durationMs=1304},
            {text="Just like it!", sound="PALVP_3C09952ADDA02C2D60DF", weight=1, durationMs=1350},
        },
        COVER_ME={
            {sound="PALVP_B295C45A38E14609AFFF", weight=1, durationMs=1583},
            {sound="PALVP_DC998E0A1ED442FE7105", weight=1, durationMs=1671},
            {text="That way, yeah, pretty good, why y'all?", sound="PALVP_634E248F26EBF177ADEF", weight=1, durationMs=1674},
            {text="Yeah, you hope it appears. Who for that?", sound="PALVP_D03951AEEA228C1D7FB8", weight=1, durationMs=1759},
            {sound="PALVP_7B07C880CA2D2A8E368E", weight=1, durationMs=1957},
