            {sound="PALVP_F803A0A992D9FF9F096F", weight=1, durationMs=1153},
        },
        FLANK_START={
            {sound="PALVP_99B0A1DECB0EA495AA8B", weight=1, durationMs=1184},
            {text="Bikaraim in that Bikaraim!", sound="PALVP_7B237E4E54B8D0E95DC1", weight=1, durationMs=1304},
            {sound="PALVP_46165F810F83A3E80C0F", weight=1, durationMs=1654},
            {sound="PALVP_9E8862423274EC764A2D", weight=1, durationMs=2138},
            {sound="PALVP_8F1D75D9D2BF91DC8E33", weight=1, durationMs=2763},
        },
        FRIENDLY_FIRE={
            {text="Let me prefer you.", sound="PALVP_8A6DA898627FD6A83E8D", weight=1, durationMs=1118},
            {sound="PALVP_BD8AA9AC0828EE4EB8B6", weight=1, durationMs=1256},
            {text="Be sure, yes, please!", sound="PALVP_4B4EDB01AE89D53544EA", weight=1, durationMs=1349},
            {text="Yes Lee, you're gonna be a sir.", sound="PALVP_FFEED7EFE389DEA37344", weight=1, durationMs=1518},
            {sound="PALVP_AACA2A4AEA15F7552C8B", weight=1, durationMs=2311},
        },
        HURT={
