        },
        COMBAT_END={
            {text="No one's dismissed.", sound="PALVP_F48943A717E8D40996F9", weight=1, durationMs=1166},
            {text="Watch those sectors!", sound="PALVP_E10AB6CA113A9AFD314D", weight=1, durationMs=1205},
            {text="Stay there you are.", sound="PALVP_4A0CD1CE54A382ABDF03", weight=1, durationMs=1218},
            {text="Fallout!", sound="PALVP_992171A6851C5EF41EA7", weight=1, durationMs=1240},
            {text="Relax, fillers!", sound="PALVP_8CDEB34CC9837C78B2C2", weight=1, durationMs=1507},
            {text="All personnel dismissed.", sound="PALVP_F34483E1435C7A4D4FBC", weight=1, durationMs=1778},
            {text="No relaxing just yet.", sound="PALVP_E6E6201B62AFA2187196", weight=1, durationMs=2042},
            {text="No sleeping, look around you!", sound="PALVP_A47F81FAFEB8A62D6ACC", weight=1, durationMs=2092},
        },
        CONTACT_HOSTILE={
            {text="Did you want to stay okay?", sound="PALVP_CC2AD9B201768998EA2B", weight=1, durationMs=1127},
            {sound="PALVP_C2374F80A2CDDF79331E", weight=1, durationMs=1238},
            {text="Moozek! Moozek!", sound="PALVP_9AA4CAF172D716D0B9BC", weight=1, durationMs=1294},
            {sound="PALVP_34E32387F3CF34E05945", weight=1, durationMs=1340},
        },
        COVER_ME={
            {sound="PALVP_94B6260A0C4279BB2861", weight=1, durationMs=1108},
            {sound="PALVP_5A6F7F1189E6FD7BFDA8", weight=1, durationMs=1401},
            {text="The bra, yeah, pre-croyo!", sound="PALVP_ED85C041D5929F8F771B", weight=1, durationMs=1617},
            {sound="PALVP_E215C5AE0D44B5DE9E5E", weight=1, durationMs=1947},
            {sound="PALVP_47E1EDE1199621943422", weight=1, durationMs=2305},
            {sound="PALVP_B025610FA00185A36544", weight=1, durationMs=1273},
        },
        FLANK_START={
            {sound="PALVP_DE49C6CDAA7A529BC7B9", weight=1, durationMs=949},
            {sound="PALVP_C2A33901D0C388173B84", weight=1, durationMs=1294},
            {sound="PALVP_DABEBE49C1CD6638172E", weight=1, durationMs=1522},
            {text="pre-croy's, how bad in you are!", sound="PALVP_C689759DE71E25285083", weight=1, durationMs=1602},
            {sound="PALVP_6B44C50A3C92ED06A584", weight=1, durationMs=2141},
        },
        FRIENDLY_FIRE={
            {sound="PALVP_996915BB655332A0C9F0", weight=1, durationMs=1308},
            {sound="PALVP_236C57B9927327A6AFB9", weight=1, durationMs=1399},
            {text="This story is so high!", sound="PALVP_D5694C630951E42F4E21", weight=1, durationMs=1532},
            {text="Yes, wake up, O'Chorta!", sound="PALVP_4D2C99CDAB68B866B105", weight=1, durationMs=1562},
            {sound="PALVP_356A335043095DE2D634", weight=1, durationMs=1785},
        },
        HURT={
            {text="God!", sound="PALVP_6822D1B1428FCF629528", weight=1, durationMs=451},
            {text="Hey!", sound="PALVP_5E8D99E14B84297E5380", weight=1, durationMs=1090},
            {sound="PALVP_BBEE55E2923E70B15D32", weight=1, durationMs=1181},
            {sound="PALVP_EF6E9894802AAAF1D5E4", weight=1, durationMs=3341},
            {sound="PALVP_06015CF2132DD2862AE9", weight=1, durationMs=4556},
            {sound="PALVP_2C41609289509C088FAA", weight=1, durationMs=4671},
            {sound="PALVP_7012F7388C8CB3033341", weight=1, durationMs=263},
            {sound="PALVP_D5C62282DBA7582A5B6C", weight=1, durationMs=303},
            {sound="PALVP_057CDFB0CA52F83CE7B7", weight=1, durationMs=377},
            {sound="PALVP_8F28C1D9BA17A1F5CB14", weight=1, durationMs=2497},
            {sound="PALVP_E924391F7A17D2323729", weight=1, durationMs=3627},
            {sound="PALVP_E97A1C4BDBF7DE8BA374", weight=1, durationMs=4775},
        },
        JOKE={
            {sound="PALVP_C7EC721DBBB6EF87C3A8", weight=1, durationMs=487},
            {sound="PALVP_7258E23035733D4B697F", weight=1, durationMs=545},
            {text="Are you on your point?", sound="PALVP_4DB2E8709B0F14BCFA71", weight=1, durationMs=780},
            {sound="PALVP_56C4268FCD5910FC265A", weight=1, durationMs=967},
            {sound="PALVP_0AE5F1A29110B082F0F7", weight=1, durationMs=975},
            {text="Ha ha!", sound="PALVP_76C195C2126DF97CC3CD", weight=1, durationMs=1007},
            {sound="PALVP_D0F7DD66526430B0D1B3", weight=1, durationMs=1073},
            {sound="PALVP_A5B21F6674EE23909291", weight=1, durationMs=1878},
            {sound="PALVP_45717CB8C58D57401945", weight=1, durationMs=9697},
        },
        KILL_CONFIRMED={
            {sound="PALVP_4DB3031D218789FB169D", weight=1, durationMs=1302},
            {text="Yay, well, please shoot it!", sound="PALVP_5007E7143AE651845F4D", weight=1, durationMs=1415},
            {text="Swaleel! Swaleel of Noah!", sound="PALVP_7258CEDD1A08229E2424", weight=1, durationMs=1874},
            {sound="PALVP_16022710A7A847109E4D", weight=1, durationMs=2183},
        },
        MOVE_OUT={
            {sound="PALVP_5184C575D80A2B0D2E60", weight=1, durationMs=1339},
            {text="Let's go work together!", sound="PALVP_AC92EE1564A65472E160", weight=1, durationMs=1498},
            {text="That's enough rest, we are moving out.", sound="PALVP_45BF6B323FC8A015A145", weight=1, durationMs=1969},
            {text="Get yourself together, we are moving out!", sound="PALVP_80D5775CAC8FDBBE88C6", weight=1, durationMs=2434},
        },
        MULTIPLE_CONTACTS={
            {sound="PALVP_054FBEDBE1028071EB99", weight=1, durationMs=999},
            {text="What did you want me to?", sound="PALVP_86B88FDBEE999701F25C", weight=1, durationMs=1060},
            {sound="PALVP_EF39AFC44A079F864C45", weight=1, durationMs=1449},
            {sound="PALVP_7FF26A15843C6FA56F3B", weight=1, durationMs=1548},
            {text="Well, you can dress up!", sound="PALVP_0A8E2B4906F45CB71F6A", weight=1, durationMs=1753},
            {text="Come on, Roscom! Hang on!", sound="PALVP_E396D01FF44D272E80C9", weight=1, durationMs=2152},
        },
        ORDER_ACK={
            {text="Roger, assemble the search party!", sound="PALVP_3E4ADFFC7B08C4A4DD62", weight=1, durationMs=3039},
        },
        RAID_START={
            {text="Fire!", sound="PALVP_5FF3D81A9A14069352EF", weight=1, durationMs=631},
            {text="Attack!", sound="PALVP_683F6EB52E36132B1C37", weight=1, durationMs=728},
            {text="Squad break into file!", sound="PALVP_BCC63C5EC44E4491FB0A", weight=1, durationMs=1529},
            {text="Go, you lazy bastard!", sound="PALVP_C2B1DB58D2C145580A1B", weight=1, durationMs=2071},
            {text="and check what's going on. The squad's not responding.", sound="PALVP_C3F50E88D5B943A6E943", weight=1, durationMs=4151},
            {text="Listen up, we've lost contact with our squad. We must find out what happened.", sound="PALVP_EA428F8F734711B0996D", weight=1, durationMs=5253},
            {text="If the team together and go see what's going on, we lost contact somehow. May I regard the door times?", sound="PALVP_6D65A771EE6722EEBF80", weight=1, durationMs=7977},
        },
        REGROUP={
            {sound="PALVP_A50321FD8FF03CF4B997", weight=1, durationMs=1316},
            {sound="PALVP_D403CB5BBA2BC499B92C", weight=1, durationMs=1421},
        },
        SEARCH_START={
            {sound="PALVP_DF7C88AC8292527B4B7F", weight=1, durationMs=2675},
            {sound="PALVP_85BD3B5A4F4B3D06DF1D", weight=1, durationMs=3058},
            {text="But I just said, Nietzsche was, it's just really just got spiny in there.", sound="PALVP_7D0930559CF688A854F6", weight=1, durationMs=3594},
            {sound="PALVP_B35B10B63A0AFFD8A191", weight=1, durationMs=4315},
        },
        SPREAD_OUT={
            {text="Attention spread out.", sound="PALVP_0DCB5C40C52C5E780782", weight=1, durationMs=1513},
        },
        STATUS_OK={
