        WARNING_LOWER_WEAPON={
            {sound="PALVP_64DF553078C0DDF5ECE4", weight=1, durationMs=929},
            {text="It's not your video, don't you?", sound="PALVP_04E88A9601258F16CA0E", weight=1, durationMs=1045},
            {sound="PALVP_BFFD19EFB45FF89B1815", weight=1, durationMs=1421},
